(function applyContractV2(data) {
  const collectionOptionals = {
    plots: ["sector", "area", "allotmentDate", "leaseDate", "possessionDate", "lat", "lon"],
    companies: ["sector", "capexClaim", "localJobClaim", "commissioningTarget", "lat", "lon"],
    interestEvents: ["date", "proposedLand", "proposedCapex", "proposedJobs", "expiry", "convertedTo", "lat", "lon"],
    housingProjects: ["legalEntity", "plot", "rera", "possessionRevisions", "rentalEvidence", "lat", "lon"],
    infrastructure: ["purpose", "officialApprovals", "funding", "failedAttempts", "dependencies", "realisticWindow", "lat", "lon"],
    clusters: ["mode", "milestone", "officialApprovals", "funding", "dependencies", "realisticWindow", "evidenceDate", "lat", "lon"],
    timelineEvents: ["currentState", "lat", "lon"]
  };
  const exactDate = /^\d{4}-\d{2}-\d{2}$/;

  function verifiedAt(value) {
    const matches = String(value || "").match(/\d{4}-\d{2}-\d{2}/g);
    return matches ? matches[matches.length - 1] : null;
  }

  function confidenceLevel(value) {
    const levels = String(value || "").toUpperCase().match(/\b(HIGH|MEDIUM|LOW)\b/g) || [];
    if (levels.includes("LOW")) return "LOW";
    if (levels.includes("MEDIUM")) return "MEDIUM";
    if (levels.includes("HIGH")) return "HIGH";
    return "UNVERIFIED";
  }

  function sourceClass(type) {
    const value = String(type || "").toLowerCase();
    if (/official|government|authority|gis|procurement|tender|statistics/.test(value)) return "OFFICIAL";
    if (/regulatory|rera|notification|framework/.test(value)) return "REGULATORY";
    if (/company|corporate|issuer|investor|operator|promoter|lender/.test(value)) return "CORPORATE";
    if (/court|legal|judgment|case/.test(value)) return "LEGAL";
    if (/research|audit|institutional/.test(value)) return "RESEARCH";
    if (/job|vacancy|salary|careers/.test(value)) return "EMPLOYMENT";
    if (/portal|marketplace|property|listing/.test(value)) return "MARKET";
    if (/media|news|press|reporting|newswire/.test(value)) return "MEDIA";
    return "OTHER";
  }

  const sourceById = new Map(data.sources.map((source) => [source.id, source]));
  const marketAssignments =
    window.REALTYPROOF_MARKET_ASSIGNMENTS?.assignments || {};
  for (const [collection, optionals] of Object.entries(collectionOptionals)) {
    for (const record of data[collection] || []) {
      for (const field of optionals) {
        if (!(field in record)) record[field] = null;
      }
      record.confidenceLevel = confidenceLevel(record.confidence);
      record.verifiedAt = verifiedAt(record.lastVerified);
      if (record.crossVerified === true) {
        record.crossVerificationStatus = "VERIFIED";
      } else if (record.crossVerified === false) {
        record.crossVerificationStatus = "NOT_VERIFIED";
      } else if ((record.sourceIds || []).length > 1) {
        record.crossVerificationStatus = "MULTI_SOURCE_UNASSESSED";
      } else {
        record.crossVerificationStatus = "SINGLE_SOURCE";
      }
      const assignment = marketAssignments[record.id] || {
        marketIds: ["gbn"],
        method: "REGIONAL_ONLY",
        confidence: "LOW",
        reviewedAt: data.meta.asOf
      };
      record.marketIds = assignment.marketIds;
      record.marketAssignmentMethod = assignment.method;
      record.marketAssignmentConfidence = assignment.confidence;
      record.marketAssignmentReviewedAt = assignment.reviewedAt;
    }
  }

  const usage = new Map();
  function countSources(value) {
    if (Array.isArray(value)) {
      value.forEach(countSources);
    } else if (value && typeof value === "object") {
      for (const [key, child] of Object.entries(value)) {
        if (key === "sourceIds" && Array.isArray(child)) {
          child.forEach((id) => usage.set(id, (usage.get(id) || 0) + 1));
        } else {
          countSources(child);
        }
      }
    }
  }
  for (const [key, value] of Object.entries(data)) {
    if (key !== "sources") countSources(value);
  }
  for (const source of data.sources) {
    source.publishedAt = exactDate.test(String(source.date)) ? source.date : null;
    source.publishedDateLabel = source.date;
    source.accessedAt = source.accessed;
    source.sourceClass = sourceClass(source.type);
    source.usageCount = usage.get(source.id) || 0;
    source.retentionStatus = source.usageCount > 0 ? "REFERENCED" : "CONTEXT_ONLY";
  }

  data.contract = {
    version: 2,
    confidenceLevels: ["HIGH", "MEDIUM", "LOW", "UNVERIFIED"],
    sourceClasses: ["OFFICIAL", "REGULATORY", "CORPORATE", "LEGAL", "RESEARCH", "MEDIA", "MARKET", "EMPLOYMENT", "OTHER"],
    datePolicy: "Machine dates use YYYY-MM-DD; descriptive publication text remains in publishedDateLabel.",
    nullablePolicy: "A present null means the field was checked but no defensible value is available."
  };
  data.marketRegistry = window.REALTYPROOF_MARKETS || {
    schemaVersion: 1,
    defaultMarket: "gbn",
    markets: []
  };
})(window.YEIDA_DATA);
